import { createFileRoute } from "@tanstack/react-router";
import { Archive, ArrowLeft, Bell, Boxes, CheckCircle2, ChevronRight, ClipboardCheck, Factory, FileText, History, LayoutDashboard, ListFilter, Menu, PackageSearch, Plus, Search, Settings2, ShieldCheck, UsersRound, Wrench, X } from "lucide-react";
import { useEffect, useMemo, useState, type FormEvent } from "react";

type AreaId = "home" | "rnd" | "stores" | "production" | "quality" | "sales" | "people";
type RecordStatus = "Draft" | "Open" | "In review" | "Approved" | "Released" | "Archived";
type RecordItem = { id: string; area: AreaId; type: string; title: string; status: RecordStatus; priority: "Low" | "Normal" | "High" | "Critical"; reference: string; createdAt: string; updatedAt: string; notes: string; links: string[]; fields: Record<string, string>; archived?: boolean };
type MasterData = { departments: string[]; people: string[]; suppliers: string[]; parts: string[]; customers: string[]; locations: string[]; routes: string[]; documentTypes: string[] };
type SetupState = { company: string; location: string; workingDays: string; timezone: string; numbering: string };
type PortalState = { setup: SetupState; setupStep: number; records: RecordItem[]; masters: MasterData; approvals: { id: string; title: string; recordId: string; outcome: "Pending" | "Approved" | "Rejected" | "Returned"; updatedAt: string }[]; documents: { id: string; title: string; url: string; type: string; recordId?: string }[]; notifications: string[] };

const areas = [
  { id: "home" as const, name: "Home / Command Center", short: "Home", icon: LayoutDashboard, summary: "Today, priority, approvals and progress", recordType: "Task" },
  { id: "rnd" as const, name: "R&D & Projects", short: "R&D", icon: Wrench, summary: "Projects, BOMs, prototype work and design gates", recordType: "Project" },
  { id: "stores" as const, name: "Purchasing & Stores", short: "Stores", icon: PackageSearch, summary: "Requests, purchase orders and stock movement", recordType: "Purchase request" },
  { id: "production" as const, name: "Production", short: "Production", icon: Factory, summary: "Work orders, testing, release and traceability", recordType: "Production order" },
  { id: "quality" as const, name: "Quality", short: "Quality", icon: ShieldCheck, summary: "Inspections, NCRs, CAPAs and actions", recordType: "Inspection" },
  { id: "sales" as const, name: "Sales & Customers", short: "Sales", icon: UsersRound, summary: "Enquiries, requirements, orders and client updates", recordType: "Enquiry" },
  { id: "people" as const, name: "People & Administration", short: "Admin", icon: Settings2, summary: "People, access, assets, policies and portal setup", recordType: "Person" },
];
const setupSteps = ["Company, locations & document numbers", "Departments & department leads", "Team members, roles & access", "Project stages & approval gates", "Parts, storage & suppliers", "Customers, pipeline & sharing rules", "Production routes & release rules", "Document naming & responsibility", "Notifications & escalation rules", "Training & go-live checklist"];
const storeKey = "six-sense-portal-v2";
const emptyPortal = (): PortalState => ({ setup: { company: "Six Sense Mobility", location: "Noida", workingDays: "Monday – Saturday", timezone: "Asia/Kolkata", numbering: "SSM-{AREA}-{YYYY}-{####}" }, setupStep: 0, records: [], masters: { departments: [], people: [], suppliers: [], parts: [], customers: [], locations: ["Noida"], routes: [], documentTypes: [] }, approvals: [], documents: [], notifications: [] });
const readPortal = () => { try { const saved = window.localStorage.getItem(storeKey); return saved ? { ...emptyPortal(), ...JSON.parse(saved) } as PortalState : emptyPortal(); } catch { return emptyPortal(); } };
const createId = () => crypto.randomUUID();
const now = () => new Date().toLocaleString("en-IN", { dateStyle: "medium", timeStyle: "short" });
const areaById = (id: AreaId) => { const area = areas.find((item) => item.id === id); if (!area) throw new Error(`Unknown area: ${id}`); return area; };

export const Route = createFileRoute("/")({
  head: () => ({ meta: [{ title: "Command Center — Six Sense Mobility" }, { name: "description", content: "Operational workspace for Six Sense Mobility in Noida." }, { property: "og:title", content: "Command Center — Six Sense Mobility" }, { property: "og:description", content: "Operational workspace and setup hub for Six Sense Mobility." }, { property: "og:type", content: "website" }, { name: "twitter:card", content: "summary_large_image" }] }),
  component: Portal,
});

function Portal() {
  const [portal, setPortal] = useState<PortalState | null>(null); const [activeArea, setActiveArea] = useState<AreaId>("home"); const [view, setView] = useState<"list" | "report" | "detail">("list"); const [selectedId, setSelectedId] = useState<string | null>(null); const [modal, setModal] = useState<"create" | "wizard" | "search" | "approvals" | "documents" | "history" | "settings" | null>(null); const [mobileMenu, setMobileMenu] = useState(false); const [notice, setNotice] = useState<string | null>(null);
  useEffect(() => setPortal(readPortal()), []);
  useEffect(() => { if (portal) window.localStorage.setItem(storeKey, JSON.stringify(portal)); }, [portal]);
  const announce = (message: string) => { setNotice(message); window.setTimeout(() => setNotice(null), 3500); };
  if (!portal) return <main className="grid min-h-screen place-items-center bg-background text-muted-foreground">Opening your portal…</main>;
  const update = (recipe: (current: PortalState) => PortalState) => setPortal((current) => current ? recipe(current) : current);
  const records = portal.records.filter((record) => !record.archived); const selected = portal.records.find((record) => record.id === selectedId) ?? undefined;
  const navigate = (area: AreaId) => { setActiveArea(area); setView("list"); setSelectedId(null); setMobileMenu(false); };
  const addRecord = (input: Omit<RecordItem, "id" | "createdAt" | "updatedAt" | "reference">) => { const number = portal.records.filter((record) => record.area === input.area).length + 1; const generatedRef = `${areaById(input.area).short.toUpperCase().replace(/&|\s/g, "").slice(0, 5)}-${String(number).padStart(4, "0")}`; const reference = input.fields.controlledNumber || generatedRef; const record = { ...input, id: createId(), reference, createdAt: now(), updatedAt: now() }; update((current) => ({ ...current, records: [record, ...current.records], notifications: [`${record.reference} created`, ...current.notifications] })); setSelectedId(record.id); setView("detail"); setModal(null); announce(`${record.reference} created and saved locally.`); };
  const updateRecord = (id: string, patch: Partial<RecordItem>) => update((current) => ({ ...current, records: current.records.map((record) => record.id === id ? { ...record, ...patch, updatedAt: now() } : record), notifications: ["Record updated", ...current.notifications] }));
  const active = areaById(activeArea);
  return <main className="min-h-screen bg-background text-foreground">
    <aside className="fixed inset-y-0 left-0 z-30 hidden w-72 border-r border-border bg-sidebar p-4 lg:flex lg:flex-col"><Brand/><nav className="mt-8 space-y-1" aria-label="Primary navigation">{areas.map((area) => <AreaNav key={area.id} area={area} active={activeArea === area.id} onClick={() => navigate(area.id)}/>)}</nav><div className="mt-auto border-t border-sidebar-border pt-4"><button onClick={() => setModal("wizard")} className="flex w-full items-center gap-3 rounded-lg bg-sidebar-accent px-3 py-3 text-left text-sm font-semibold text-sidebar-accent-foreground"><Settings2 className="size-4"/>Portal setup <span className="ml-auto font-mono text-[10px]">{portal.setupStep + 1}/10</span></button></div></aside>
    <section className="min-h-screen lg:pl-72"><header className="sticky top-0 z-20 border-b border-border bg-background/95 backdrop-blur-md"><div className="flex h-16 items-center gap-3 px-4 md:px-8"><button aria-label="Open menu" onClick={() => setMobileMenu(true)} className="grid size-10 place-items-center rounded-lg border border-border bg-panel lg:hidden"><Menu className="size-4"/></button><button onClick={() => navigate("home")} className="min-w-0 flex-1 text-left"><p className="truncate text-sm font-semibold md:text-base">{active.name}</p><p className="font-mono text-[10px] uppercase tracking-[0.14em] text-muted-foreground">All departments · {portal.setup["location"] || "Noida"}</p></button><HeaderAction label="Search" icon={Search} onClick={() => setModal("search")}/><HeaderAction label="Notifications" icon={Bell} onClick={() => setModal("history")}/></div></header>
      <div className="mx-auto max-w-7xl px-4 pb-28 pt-6 md:px-8 md:pt-8 lg:pb-10">{activeArea === "home" ? <Dashboard portal={portal} onArea={navigate} onCreate={(area) => { setActiveArea(area); setModal("create"); }} onUtility={setModal} onSetup={() => setModal("wizard")}/> : <AreaWorkspace area={active} records={records.filter((record) => record.area === activeArea)} view={view} selected={selected} onView={setView} onSelect={(record) => { setSelectedId(record.id); setView("detail"); }} onCreate={() => setModal("create")} onBack={() => { setView("list"); setSelectedId(null); }} onUpdate={updateRecord} onArchive={(id) => { updateRecord(id, { archived: true, status: "Archived" }); setView("list"); announce("Record archived. It remains in history for recovery."); }} />}</div>
    </section>
    <nav className="fixed inset-x-0 bottom-0 z-30 grid grid-cols-5 border-t border-border bg-background/95 px-1 pb-[max(0.5rem,env(safe-area-inset-bottom))] pt-1 backdrop-blur-md lg:hidden" aria-label="Mobile navigation">{areas.slice(0, 4).map((area) => <button key={area.id} onClick={() => navigate(area.id)} className={`flex min-h-14 flex-col items-center justify-center gap-1 rounded-md text-[10px] ${activeArea === area.id ? "bg-accent text-accent-foreground" : "text-muted-foreground"}`}><area.icon className="size-4"/><span>{area.short}</span></button>)}<button onClick={() => setMobileMenu(true)} className="flex min-h-14 flex-col items-center justify-center gap-1 rounded-md text-[10px] text-muted-foreground"><Menu className="size-4"/><span>More</span></button></nav>
    {mobileMenu && <div className="fixed inset-0 z-50 bg-ink/30 lg:hidden"><div className="h-full w-[min(19rem,88vw)] bg-sidebar p-4 shadow-xl"><div className="flex items-center justify-between"><Brand/><button className="grid size-10 place-items-center rounded-lg border border-border" onClick={() => setMobileMenu(false)} aria-label="Close menu"><X className="size-4"/></button></div><nav className="mt-8 space-y-1">{areas.map((area) => <AreaNav key={area.id} area={area} active={activeArea === area.id} onClick={() => navigate(area.id)}/>)}</nav></div></div>}
    {modal === "create" && <RecordForm area={activeArea} portal={portal} onClose={() => setModal(null)} onSave={addRecord}/>} {modal === "wizard" && <Wizard portal={portal} onClose={() => setModal(null)} onSave={(next) => { update(() => next); announce("Setup progress saved locally."); }}/>} {modal === "search" && <SearchPanel records={records} onClose={() => setModal(null)} onSelect={(record) => { setActiveArea(record.area); setSelectedId(record.id); setView("detail"); setModal(null); }}/>} {modal === "approvals" && <ApprovalsPanel portal={portal} update={update} onClose={() => setModal(null)} onOpen={(record) => { setActiveArea(record.area); setSelectedId(record.id); setView("detail"); setModal(null); }}/>} {modal === "documents" && <DocumentsPanel portal={portal} update={update} onClose={() => setModal(null)} announce={announce}/>} {modal === "history" && <HistoryPanel portal={portal} onClose={() => setModal(null)}/>} {modal === "settings" && <SettingsPanel portal={portal} update={update} onClose={() => setModal(null)} announce={announce}/>} {notice && <div role="status" className="fixed bottom-20 left-4 right-4 z-[60] border border-border bg-ink px-4 py-3 text-sm text-primary-foreground shadow-lg lg:bottom-6 lg:left-auto lg:right-6 lg:w-96">{notice}</div>}
  </main>;
}

function Dashboard({ portal, onArea, onCreate, onUtility, onSetup }: { portal: PortalState; onArea: (area: AreaId) => void; onCreate: (area: AreaId) => void; onUtility: (modal: "approvals" | "documents" | "history" | "settings") => void; onSetup: () => void }) { const activeRecords = portal.records.filter((record) => !record.archived); const completion = Math.round(((portal.setupStep + 1) / 10) * 100); return <><div className="mb-6 grid gap-3 md:grid-cols-[minmax(0,1fr)_auto] md:items-end"><div><p className="font-mono text-[10px] uppercase tracking-[0.18em] text-moss">Operational workspace</p><h1 className="mt-2 text-3xl font-semibold md:text-4xl">Command center</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-muted-foreground">Create your own operational records. Nothing appears here until your team adds it.</p></div><button onClick={onSetup} className="inline-flex h-11 items-center justify-center gap-2 rounded-lg bg-primary px-4 text-sm font-semibold text-primary-foreground"><Settings2 className="size-4"/>Continue setup</button></div><section className="border border-border bg-card p-4 md:p-5"><div className="grid gap-4 md:grid-cols-[minmax(0,1fr)_auto]"><div><p className="font-semibold">Setup completeness</p><p className="mt-2 text-sm text-muted-foreground">Company and Noida are ready. Continue the guided setup when confirmed information becomes available.</p></div><div className="min-w-[200px]"><div className="mb-2 flex justify-between font-mono text-[10px] uppercase tracking-[0.14em] text-muted-foreground"><span>Setup</span><span>{completion}%</span></div><div className="h-2 overflow-hidden rounded-full bg-panel-strong"><div className="h-full rounded-full bg-steel" style={{ width: `${completion}%` }}/></div></div></div></section><section className="mt-6 grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Open records" value={String(activeRecords.length)} detail="Across all work areas" tone="steel"/><Metric label="High priority" value={String(activeRecords.filter((record) => record.priority === "High" || record.priority === "Critical").length)} detail="Needs attention" tone="danger"/><Metric label="Approvals" value={String(portal.approvals.filter((approval) => approval.outcome === "Pending").length)} detail="Awaiting a human" tone="moss"/><Metric label="Documents" value={String(portal.documents.length)} detail="Linked references" tone="warning"/></section><section className="mt-6 grid gap-4 xl:grid-cols-[minmax(0,1fr)_21rem]"><div className="border border-border bg-card"><div className="flex items-center justify-between border-b border-border px-4 py-3"><div><p className="font-semibold">Daily queue</p><p className="text-xs text-muted-foreground">Open records created across the portal</p></div><button onClick={() => onArea("rnd")} className="font-mono text-[10px] uppercase tracking-[0.12em] text-steel">View records</button></div>{activeRecords.length ? <div>{activeRecords.slice(0, 5).map((record) => <button key={record.id} onClick={() => { onArea(record.area); }} className="flex w-full items-center justify-between border-b border-border px-4 py-3 text-left last:border-0"><span><span className="font-mono text-[10px] text-muted-foreground">{record.reference}</span><span className="ml-2 text-sm font-medium">{record.title}</span></span><Status status={record.status}/></button>)}</div> : <Empty onCreate={() => onCreate("rnd")}/>}</div><aside className="border border-border bg-panel p-4"><p className="font-semibold">Global utilities</p><div className="mt-3 grid gap-2">{[["Tasks", "rnd" as AreaId], ["Approvals", "approvals"], ["Documents", "documents"], ["History", "history"], ["Administration settings", "settings"]].map(([label, target]) => <button key={label} onClick={() => typeof target === "string" && areas.some((area) => area.id === target) ? onArea(target as AreaId) : onUtility(target as "approvals" | "documents" | "history" | "settings")} className="flex min-h-11 items-center justify-between rounded-md border border-border bg-card px-3 text-left text-sm font-medium hover:bg-secondary"><span>{label}</span><ChevronRight className="size-4 text-muted-foreground"/></button>)}</div></aside></section><section className="mt-8"><div className="mb-3 flex items-center justify-between"><div><h2 className="text-base font-semibold">Seven areas</h2><p className="text-xs text-muted-foreground">Each opens a working queue, record detail and summary.</p></div><Boxes className="size-5 text-muted-foreground"/></div><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{areas.slice(1).map((area) => <button key={area.id} onClick={() => onArea(area.id)} className="min-h-36 border border-border bg-card p-4 text-left hover:bg-secondary"><area.icon className="size-5 text-steel"/><h3 className="mt-5 font-semibold">{area.name}</h3><p className="mt-2 text-xs leading-5 text-muted-foreground">{area.summary}</p><p className="mt-4 font-mono text-[10px] uppercase tracking-[0.15em] text-moss">Open workspace</p></button>)}</div></section></>; }
function AreaWorkspace({ area, records, view, selected, onView, onSelect, onCreate, onBack, onUpdate, onArchive }: { area: ReturnType<typeof areaById>; records: RecordItem[]; view: "list" | "report" | "detail"; selected: RecordItem | undefined; onView: (view: "list" | "report" | "detail") => void; onSelect: (record: RecordItem) => void; onCreate: () => void; onBack: () => void; onUpdate: (id: string, patch: Partial<RecordItem>) => void; onArchive: (id: string) => void }) { const [query, setQuery] = useState(""); const [status, setStatus] = useState("All"); const [sort, setSort] = useState("Newest"); const shown = [...records].filter((record) => (status === "All" || record.status === status) && `${record.title} ${record.reference} ${record.type}`.toLowerCase().includes(query.toLowerCase())).sort((a, b) => sort === "Title" ? a.title.localeCompare(b.title) : b.updatedAt.localeCompare(a.updatedAt)); if (view === "detail" && selected) return <RecordDetail record={selected} onBack={onBack} onUpdate={onUpdate} onArchive={onArchive}/>; if (view === "report") return <AreaReport area={area} records={records} onBack={() => onView("list")}/>; return <><div className="mb-6 flex flex-wrap items-end justify-between gap-4"><div><p className="font-mono text-[10px] uppercase tracking-[0.18em] text-moss">{area.short} workspace</p><h1 className="mt-2 text-3xl font-semibold">{area.name}</h1><p className="mt-2 text-sm text-muted-foreground">Queue, records and controls for {area.summary.toLowerCase()}.</p></div><div className="flex gap-2"><button onClick={() => onView("report")} className="h-11 rounded-md border border-border bg-card px-4 text-sm font-semibold">Summary</button><button onClick={onCreate} className="inline-flex h-11 items-center gap-2 rounded-md bg-primary px-4 text-sm font-semibold text-primary-foreground"><Plus className="size-4"/>Create {area.recordType}</button></div></div><div className="border border-border bg-card"><div className="flex flex-wrap gap-2 border-b border-border p-3"><label className="flex min-w-48 flex-1 items-center gap-2 rounded-md border border-input bg-background px-3"><Search className="size-4 text-muted-foreground"/><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder={`Search ${area.recordType.toLowerCase()} records`} className="h-10 min-w-0 flex-1 bg-transparent text-sm outline-none"/></label><select aria-label="Filter status" value={status} onChange={(event) => setStatus(event.target.value)} className="h-10 rounded-md border border-input bg-background px-3 text-sm"><option>All</option>{["Draft", "Open", "In review", "Approved", "Released"].map((option) => <option key={option}>{option}</option>)}</select><select aria-label="Sort records" value={sort} onChange={(event) => setSort(event.target.value)} className="h-10 rounded-md border border-input bg-background px-3 text-sm"><option>Newest</option><option>Title</option></select></div>{shown.length ? <div>{shown.map((record) => <button key={record.id} onClick={() => onSelect(record)} className="grid w-full gap-3 border-b border-border px-4 py-4 text-left last:border-0 md:grid-cols-[8rem_minmax(0,1fr)_8rem_7rem]"><span className="font-mono text-xs text-muted-foreground">{record.reference}</span><span><span className="block font-semibold">{record.title}</span><span className="mt-1 block text-xs text-muted-foreground">{record.type} · Updated {record.updatedAt}</span></span><Status status={record.status}/><span className="font-mono text-[10px] uppercase text-muted-foreground">{record.priority}</span></button>)}</div> : <Empty onCreate={onCreate} label={`Create ${area.recordType}`}/>}</div></>; }
function RecordDetail({ record, onBack, onUpdate, onArchive }: { record: RecordItem; onBack: () => void; onUpdate: (id: string, patch: Partial<RecordItem>) => void; onArchive: (id: string) => void }) { const [editing, setEditing] = useState(false); const [title, setTitle] = useState(record.title); const [notes, setNotes] = useState(record.notes); const [status, setStatus] = useState<RecordStatus>(record.status); return <><button onClick={onBack} className="mb-5 inline-flex items-center gap-2 text-sm font-semibold text-steel"><ArrowLeft className="size-4"/>Back to queue</button><section className="border border-border bg-card"><div className="flex flex-wrap items-start justify-between gap-4 border-b border-border p-5"><div><p className="font-mono text-xs text-muted-foreground">{record.reference} · {record.type}</p><h1 className="mt-2 text-3xl font-semibold">{record.title}</h1><p className="mt-2 text-sm text-muted-foreground">Created {record.createdAt} · Updated {record.updatedAt}</p></div><div className="flex gap-2"><button onClick={() => setEditing(!editing)} className="h-10 rounded-md border border-border px-3 text-sm font-semibold">{editing ? "Cancel" : "Edit"}</button><button onClick={() => onArchive(record.id)} className="inline-flex h-10 items-center gap-2 rounded-md border border-border px-3 text-sm font-semibold text-danger"><Archive className="size-4"/>Archive</button></div></div><div className="grid gap-6 p-5 md:grid-cols-[minmax(0,1fr)_16rem]"><div>{editing ? <form onSubmit={(event) => { event.preventDefault(); if (!title.trim()) return; onUpdate(record.id, { title: title.trim(), notes: notes.slice(0, 2000), status }); setEditing(false); }} className="space-y-4"><TextField label="Title" value={title} onChange={setTitle} required/><label className="block text-sm font-medium">Status<select value={status} onChange={(event) => setStatus(event.target.value as RecordStatus)} className="mt-1.5 h-11 w-full rounded-md border border-input bg-background px-3 text-sm">{["Draft", "Open", "In review", "Approved", "Released"].map((option) => <option key={option}>{option}</option>)}</select></label><label className="block text-sm font-medium">Notes<textarea value={notes} onChange={(event) => setNotes(event.target.value.slice(0, 2000))} className="mt-1.5 min-h-28 w-full rounded-md border border-input bg-background p-3 text-sm"/></label><button className="h-10 rounded-md bg-primary px-4 text-sm font-semibold text-primary-foreground">Save changes</button></form> : <><h2 className="font-semibold">Controlled fields</h2><dl className="mt-3 grid gap-3 sm:grid-cols-2">{Object.entries(record.fields).filter(([, value]) => value).map(([key, value]) => <div key={key} className="border-b border-border pb-2"><dt className="font-mono text-[10px] uppercase tracking-[0.12em] text-muted-foreground">{key.replace(/([A-Z])/g, " $1")}</dt><dd className="mt-1 text-sm">{value}</dd></div>)}</dl><h2 className="mt-6 font-semibold">Requirements / scope</h2><p className="mt-2 whitespace-pre-wrap text-sm leading-6 text-muted-foreground">{record.notes || "No scope added."}</p><h2 className="mt-6 font-semibold">Linked workflow</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">{record.links.length ? `${record.links.length} linked record${record.links.length === 1 ? "" : "s"} saved with this record.` : "No linked records selected yet."}</p></>}</div><aside className="border-l border-border pl-5"><p className="font-mono text-[10px] uppercase tracking-[0.14em] text-muted-foreground">Current state</p><div className="mt-3"><Status status={record.status}/></div><p className="mt-6 font-mono text-[10px] uppercase tracking-[0.14em] text-muted-foreground">Priority</p><p className="mt-2 text-sm font-semibold">{record.priority}</p><p className="mt-6 font-mono text-[10px] uppercase tracking-[0.14em] text-muted-foreground">Audit history</p><p className="mt-2 text-sm text-muted-foreground">Created {record.createdAt}<br/>Updated {record.updatedAt}</p></aside></div></section></>; }
function AreaReport({ area, records, onBack }: { area: ReturnType<typeof areaById>; records: RecordItem[]; onBack: () => void }) { const byStatus = ["Draft", "Open", "In review", "Approved", "Released"].map((status) => [status, records.filter((record) => record.status === status).length] as const); return <><button onClick={onBack} className="mb-5 inline-flex items-center gap-2 text-sm font-semibold text-steel"><ArrowLeft className="size-4"/>Back to queue</button><div className="mb-6"><p className="font-mono text-[10px] uppercase tracking-[0.18em] text-moss">{area.short} report</p><h1 className="mt-2 text-3xl font-semibold">Record summary</h1><p className="mt-2 text-sm text-muted-foreground">Live totals from records created in this workspace.</p></div><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5">{byStatus.map(([status, count]) => <Metric key={status} label={status} value={String(count)} detail="Records" tone={status === "Open" ? "steel" : status === "Approved" || status === "Released" ? "moss" : "warning"}/>)}</div></>; }
const formSpecs: Record<Exclude<AreaId, "home">, { types: string[]; fields: { key: string; label: string; required?: boolean; kind?: "text" | "date" | "select"; options?: string[]; master?: keyof MasterData }[]; links: { label: string; areas: AreaId[] }[] }> = {
  rnd: { types: ["Project", "Part", "BOM", "Prototype", "Engineering change", "Design review"], fields: [{ key: "controlledNumber", label: "Project code / controlled number", required: true }, { key: "title", label: "Project title", required: true }, { key: "category", label: "Type / category", required: true, kind: "select", options: ["New product", "Variant", "Research", "Sustaining engineering"] }, { key: "customer", label: "Customer", master: "customers" }, { key: "product", label: "Product" }, { key: "owner", label: "Owner", required: true, master: "people" }, { key: "team", label: "Team", master: "departments" }, { key: "stage", label: "Stage", required: true, kind: "select", options: ["Concept", "Requirements", "Prototype", "Verification", "Released"] }, { key: "startDate", label: "Start date", kind: "date" }, { key: "targetDate", label: "Target date", kind: "date" }, { key: "location", label: "Location", required: true, master: "locations" }], links: [{ label: "Tasks", areas: ["home"] }, { label: "BOM / prototype / engineering change", areas: ["rnd"] }, { label: "Quality review / gate", areas: ["quality"] }] },
  stores: { types: ["Part", "Supplier", "Purchase request", "RFQ", "Purchase order", "Receiving", "Stock movement"], fields: [{ key: "controlledNumber", label: "Controlled number", required: true }, { key: "title", label: "Title", required: true }, { key: "category", label: "Transaction type", required: true, kind: "select", options: ["Part", "Supplier", "Purchase request", "RFQ", "Purchase order", "Receiving", "Stock movement"] }, { key: "supplier", label: "Supplier", master: "suppliers" }, { key: "part", label: "Part", master: "parts" }, { key: "owner", label: "Owner", required: true, master: "people" }, { key: "location", label: "Location", required: true, master: "locations" }, { key: "requiredDate", label: "Required date", kind: "date" }], links: [{ label: "Project", areas: ["rnd"] }, { label: "Production order", areas: ["production"] }] },
  production: { types: ["Work order", "Production test", "Release", "Dispatch"], fields: [{ key: "controlledNumber", label: "Work order number", required: true }, { key: "title", label: "Title", required: true }, { key: "category", label: "Record type", required: true, kind: "select", options: ["Work order", "Production test", "Release", "Dispatch"] }, { key: "route", label: "Production route", master: "routes" }, { key: "owner", label: "Owner", required: true, master: "people" }, { key: "location", label: "Location", required: true, master: "locations" }, { key: "startDate", label: "Planned start", kind: "date" }, { key: "targetDate", label: "Planned completion", kind: "date" }], links: [{ label: "Project / BOM", areas: ["rnd"] }, { label: "Parts / purchase", areas: ["stores"] }, { label: "Quality inspection", areas: ["quality"] }] },
  quality: { types: ["Inspection", "NCR", "CAPA", "Quality review"], fields: [{ key: "controlledNumber", label: "Quality record number", required: true }, { key: "title", label: "Title", required: true }, { key: "category", label: "Record type", required: true, kind: "select", options: ["Inspection", "NCR", "CAPA", "Quality review"] }, { key: "owner", label: "Owner", required: true, master: "people" }, { key: "location", label: "Location", required: true, master: "locations" }, { key: "targetDate", label: "Target closure", kind: "date" }], links: [{ label: "Project", areas: ["rnd"] }, { label: "Production work order", areas: ["production"] }, { label: "Supplier / receiving", areas: ["stores"] }] },
  sales: { types: ["Customer", "Enquiry", "Opportunity", "Order", "Handover"], fields: [{ key: "controlledNumber", label: "Commercial record number", required: true }, { key: "title", label: "Title", required: true }, { key: "category", label: "Record type", required: true, kind: "select", options: ["Customer", "Enquiry", "Opportunity", "Order", "Handover"] }, { key: "customer", label: "Customer", master: "customers" }, { key: "owner", label: "Owner", required: true, master: "people" }, { key: "targetDate", label: "Target date", kind: "date" }, { key: "location", label: "Location", required: true, master: "locations" }], links: [{ label: "Project", areas: ["rnd"] }, { label: "Production / dispatch", areas: ["production"] }] },
  people: { types: ["Person", "Training", "Leave", "Asset"], fields: [{ key: "controlledNumber", label: "Controlled number", required: true }, { key: "title", label: "Name / title", required: true }, { key: "category", label: "Record type", required: true, kind: "select", options: ["Person", "Training", "Leave", "Asset"] }, { key: "department", label: "Department", master: "departments" }, { key: "owner", label: "Responsible person", master: "people" }, { key: "location", label: "Location", required: true, master: "locations" }, { key: "targetDate", label: "Due date", kind: "date" }], links: [{ label: "Training / quality", areas: ["quality"] }, { label: "Project", areas: ["rnd"] }] },
};
function RecordForm({ area, portal, onClose, onSave }: { area: AreaId; portal: PortalState; onClose: () => void; onSave: (record: Omit<RecordItem, "id" | "createdAt" | "updatedAt" | "reference">) => void }) { if (area === "home") return null; const spec = formSpecs[area]; if (!spec) return null; const [type, setType] = useState(spec.types[0] ?? "Record"); const [values, setValues] = useState<Record<string, string>>({}); const [links, setLinks] = useState<string[]>([]); const [error, setError] = useState(""); const field = (key: string) => values[key] ?? ""; const addLinked = (linkedArea: AreaId) => { const linkedType = areaById(linkedArea).recordType; const linkedTitle = window.prompt(`Create ${linkedType} title`); if (!linkedTitle?.trim()) return; const id = createId(); setLinks((current) => [...current, id]); onSave({ area: linkedArea, type: linkedType, title: linkedTitle.trim().slice(0, 120), status: "Draft", priority: "Normal", notes: "Created from a linked-record selector.", links: [], fields: {} }); }; const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const missing = spec.fields.find((item) => item.required && !field(item.key).trim()); if (missing) return setError(`${missing.label} is required.`); const title = field("title").trim(); if (title.length > 120) return setError("Title must be 120 characters or fewer."); onSave({ area, type, title, status: "Draft", priority: "Normal", notes: field("scope").trim(), links, fields: values }); }; return <Modal title={`Create ${type}`} onClose={onClose} wide><form onSubmit={submit} className="space-y-5"><div className="grid gap-4 md:grid-cols-2"><label className="block text-sm font-medium">Record type<select value={type} onChange={(event) => setType(event.target.value)} className="mt-1.5 h-11 w-full rounded-md border border-input bg-background px-3 text-sm">{spec.types.map((option) => <option key={option}>{option}</option>)}</select></label>{spec.fields.map((item) => <FormField key={item.key} item={item} value={field(item.key)} onChange={(value) => setValues({ ...values, [item.key]: value })} portal={portal}/>)}</div><label className="block text-sm font-medium">Requirements / scope<textarea value={field("scope")} onChange={(event) => setValues({ ...values, scope: event.target.value.slice(0, 2000) })} maxLength={2000} className="mt-1.5 min-h-28 w-full rounded-md border border-input bg-background p-3 text-sm"/></label><div className="border-t border-border pt-4"><p className="font-semibold">Linked records</p><div className="mt-3 grid gap-3 md:grid-cols-2">{spec.links.map((item) => <LinkedSelector key={item.label} label={item.label} records={portal.records.filter((record) => item.areas.includes(record.area))} links={links} onChange={setLinks} onCreate={() => addLinked(item.areas[0] ?? area)}/>)}</div></div>{error && <p role="alert" className="text-sm text-danger">{error}</p>}<div className="flex justify-end gap-2"><button type="button" onClick={onClose} className="h-10 rounded-md px-4 text-sm font-semibold text-muted-foreground">Cancel</button><button className="h-10 rounded-md bg-primary px-4 text-sm font-semibold text-primary-foreground">Save {type}</button></div></form></Modal>; }
function Wizard({ portal, onClose, onSave }: { portal: PortalState; onClose: () => void; onSave: (next: PortalState) => void }) { const [step, setStep] = useState(portal.setupStep); const [setup, setSetup] = useState(portal.setup); const [message, setMessage] = useState(""); const fields = step === 0 ? <><TextField label="Company name" required value={setup["company"] ?? ""} onChange={(company) => setSetup({ ...setup, company })}/><TextField label="Main location" required value={setup["location"] ?? ""} onChange={(location) => setSetup({ ...setup, location })}/><label className="block text-sm font-medium">Working days<select value={setup["workingDays"] ?? "Monday – Saturday"} onChange={(event) => setSetup({ ...setup, workingDays: event.target.value })} className="mt-1.5 h-11 w-full rounded-md border border-input bg-background px-3 text-sm"><option>Monday – Friday</option><option>Monday – Saturday</option><option>Monday – Sunday</option><option>Custom schedule</option></select></label><label className="block text-sm font-medium">Date &amp; time preference<select value={setup["timezone"] ?? "Asia/Kolkata"} onChange={(event) => setSetup({ ...setup, timezone: event.target.value })} className="mt-1.5 h-11 w-full rounded-md border border-input bg-background px-3 text-sm"><option>Asia/Kolkata</option><option>UTC</option></select></label><label className="block text-sm font-medium">Document numbering<select value={setup["numbering"] ?? "SSM-AREA-YYYY-####"} onChange={(event) => setSetup({ ...setup, numbering: event.target.value })} className="mt-1.5 h-11 w-full rounded-md border border-input bg-background px-3 text-sm"><option>SSM-AREA-YYYY-####</option><option>AREA-YYYY-####</option><option>Custom pattern</option></select></label></> : <MasterStep step={step} portal={portal} onSave={onSave} message={message} setMessage={setMessage}/>; const saveProgress = () => onSave({ ...portal, setup, setupStep: step }); return <Modal title={setupSteps[step] ?? "Portal setup"} onClose={onClose} wide><div className="mb-5 flex justify-between font-mono text-[10px] uppercase tracking-[0.14em] text-muted-foreground"><span>Step {step + 1} of 10</span><span>{Math.round(((step + 1) / 10) * 100)}%</span></div><div className="mb-5 h-2 overflow-hidden rounded-full bg-panel-strong"><div className="h-full rounded-full bg-steel" style={{ width: `${((step + 1) / 10) * 100}%` }}/></div><div className="grid gap-5 md:grid-cols-[13rem_minmax(0,1fr)]"><ol className="grid grid-cols-2 gap-1 md:block">{setupSteps.map((name, index) => <li key={name}><button onClick={() => { saveProgress(); setStep(index); }} className={`w-full rounded-md px-2 py-2 text-left font-mono text-[10px] leading-4 ${index === step ? "bg-accent text-accent-foreground" : "text-muted-foreground"}`}>{String(index + 1).padStart(2, "0")} · {name}</button></li>)}</ol><div className="space-y-4"><p className="text-sm leading-6 text-muted-foreground">{step === 0 ? "Confirmed company and location details are prefilled. Choose the operating options you need." : "Add only confirmed master data. It becomes available in relevant selectors across the portal."}</p>{fields}{message && <p role="status" className="text-sm text-moss">{message}</p>}</div></div><footer className="mt-6 flex justify-between border-t border-border pt-4"><button onClick={() => { saveProgress(); setStep(Math.max(0, step - 1)); }} disabled={step === 0} className="h-10 rounded-md border border-border px-4 text-sm font-semibold disabled:opacity-40">Back</button><div className="flex gap-2"><button onClick={() => { saveProgress(); onClose(); }} className="h-10 rounded-md px-4 text-sm font-semibold text-muted-foreground">Save &amp; resume</button><button onClick={() => { const next = Math.min(9, step + 1); onSave({ ...portal, setup, setupStep: next }); if (step === 9) onClose(); else setStep(next); }} className="h-10 rounded-md bg-primary px-4 text-sm font-semibold text-primary-foreground">{step === 9 ? "Save checklist" : "Next step"}</button></div></footer></Modal>; }
function MasterStep({ step, portal, onSave, message, setMessage }: { step: number; portal: PortalState; onSave: (next: PortalState) => void; message: string; setMessage: (value: string) => void }) { const configs: Record<number, { key: keyof MasterData; label: string }> = { 1: { key: "departments", label: "Department" }, 2: { key: "people", label: "Team member" }, 4: { key: "parts", label: "Part / storage / supplier" }, 5: { key: "customers", label: "Customer" }, 6: { key: "routes", label: "Production route" }, 7: { key: "documentTypes", label: "Document type" } }; const config = configs[step]; if (!config) return <SetupMessage step={step}/>; const values = portal.masters[config.key] ?? []; return <div className="rounded-md border border-dashed border-border bg-panel p-4"><p className="font-semibold">{config.label}s</p><p className="mt-1 text-sm text-muted-foreground">Create confirmed options for this portal. No examples have been added.</p><div className="mt-3 flex gap-2"><input id="new-master" className="h-10 min-w-0 flex-1 rounded-md border border-input bg-background px-3 text-sm" placeholder={`New ${config.label.toLowerCase()}`}/><button onClick={() => { const input = document.getElementById("new-master") as HTMLInputElement | null; const value = input?.value.trim(); if (!value) return setMessage(`Enter a ${config.label.toLowerCase()} name first.`); if (values.includes(value)) return setMessage("That option already exists."); onSave({ ...portal, masters: { ...portal.masters, [config.key]: [...values, value] } }); if (input) input.value = ""; setMessage(`${value} added.`); }} className="h-10 rounded-md bg-primary px-3 text-sm font-semibold text-primary-foreground">Add</button></div>{values.length ? <ul className="mt-3 space-y-2">{values.map((value) => <li key={value} className="flex items-center justify-between text-sm"><span>{value}</span><button onClick={() => onSave({ ...portal, masters: { ...portal.masters, [config.key]: values.filter((item) => item !== value) } })} className="text-danger">Deactivate</button></li>)}</ul> : <p className="mt-3 text-sm text-muted-foreground">No {config.label.toLowerCase()} records yet.</p>}</div>; }
function SetupMessage({ step }: { step: number }) { return <div className="rounded-md border border-dashed border-border bg-panel p-4"><p className="font-semibold">Information needed</p><p className="mt-2 text-sm leading-6 text-muted-foreground">{["", "", "", "Set the review stages and human approval gates for design work.", "", "", "", "", "Create notification and escalation rules.", "Prepare training evidence and the go-live checklist."][step]}</p><p className="mt-4 font-mono text-[10px] uppercase tracking-[0.14em] text-muted-foreground">{step < 7 ? "Required before go-live" : "Optional — can be added later"}</p></div>; }
function SearchPanel({ records, onClose, onSelect }: { records: RecordItem[]; onClose: () => void; onSelect: (record: RecordItem) => void }) { const [query, setQuery] = useState(""); const results = records.filter((record) => `${record.title} ${record.reference} ${record.type}`.toLowerCase().includes(query.toLowerCase())); return <Modal title="Search portal records" onClose={onClose}><label className="flex items-center gap-2 rounded-md border border-input bg-background px-3"><Search className="size-4 text-muted-foreground"/><input autoFocus value={query} onChange={(event) => setQuery(event.target.value)} className="h-11 flex-1 bg-transparent text-sm outline-none" placeholder="Search records by name or reference"/></label><div className="mt-4">{results.length ? results.map((record) => <button key={record.id} onClick={() => onSelect(record)} className="flex w-full items-center justify-between border-b border-border py-3 text-left"><span><span className="block text-sm font-semibold">{record.title}</span><span className="font-mono text-[10px] text-muted-foreground">{record.reference} · {areaById(record.area).short}</span></span><ChevronRight className="size-4 text-muted-foreground"/></button>) : <p className="py-8 text-center text-sm text-muted-foreground">No matching records yet.</p>}</div></Modal>; }
function ApprovalsPanel({ portal, update, onClose, onOpen }: { portal: PortalState; update: (recipe: (current: PortalState) => PortalState) => void; onClose: () => void; onOpen: (record: RecordItem) => void }) { return <Modal title="Human approvals" onClose={onClose}><p className="mb-4 text-sm leading-6 text-muted-foreground">Approvals are explicitly performed by a person. Automation cannot approve controlled operations.</p>{portal.approvals.length ? portal.approvals.map((approval) => <div key={approval.id} className="border-b border-border py-3"><p className="font-semibold">{approval.title}</p><p className="mt-1 text-xs text-muted-foreground">{approval.outcome} · {approval.updatedAt}</p>{approval.outcome === "Pending" && <div className="mt-3 flex gap-2">{(["Approved", "Rejected", "Returned"] as const).map((outcome) => <button key={outcome} onClick={() => update((current) => ({ ...current, approvals: current.approvals.map((item) => item.id === approval.id ? { ...item, outcome, updatedAt: now() } : item) }))} className="h-9 rounded-md border border-border px-3 text-sm font-semibold">{outcome}</button>)}</div>}</div>) : <p className="py-8 text-center text-sm text-muted-foreground">No approvals are awaiting a human decision.</p>}</Modal>; }
function DocumentsPanel({ portal, update, onClose, announce }: { portal: PortalState; update: (recipe: (current: PortalState) => PortalState) => void; onClose: () => void; announce: (message: string) => void }) { const [title, setTitle] = useState(""); const [url, setUrl] = useState(""); const add = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); const titleValue = title.trim(); const urlValue = url.trim(); if (!titleValue || !urlValue) return announce("Add a document title and reference link."); update((current) => ({ ...current, documents: [{ id: createId(), title: titleValue, url: urlValue, type: String(data.get("type")), ...{}, }, ...current.documents] })); setTitle(""); setUrl(""); event.currentTarget.reset(); announce("Document reference added."); }; return <Modal title="Document references" onClose={onClose}><form onSubmit={add} className="grid gap-3 border-b border-border pb-4"><TextField name="title" label="Document title" value={title} onChange={setTitle} required/><TextField name="url" label="Reference link" value={url} onChange={setUrl} required type="url"/><label className="text-sm font-medium">Type<select name="type" className="mt-1.5 h-11 w-full rounded-md border border-input bg-background px-3 text-sm"><option>Specification</option><option>Drawing</option><option>Procedure</option><option>Other</option></select></label><button className="h-10 rounded-md bg-primary px-4 text-sm font-semibold text-primary-foreground">Add reference</button></form><div className="mt-4">{portal.documents.map((document) => <a key={document.id} href={document.url} target="_blank" rel="noreferrer" className="block border-b border-border py-3"><span className="block text-sm font-semibold">{document.title}</span><span className="text-xs text-muted-foreground">{document.type}</span></a>)}</div></Modal>; }
function HistoryPanel({ portal, onClose }: { portal: PortalState; onClose: () => void }) { return <Modal title="Notifications & history" onClose={onClose}><div className="space-y-3">{portal.notifications.length ? portal.notifications.map((item, index) => <p key={`${item}-${index}`} className="border-b border-border pb-3 text-sm">{item}</p>) : <p className="py-8 text-center text-sm text-muted-foreground">No history yet. Your saved actions will appear here.</p>}</div></Modal>; }
function SettingsPanel({ portal, update, onClose, announce }: { portal: PortalState; update: (recipe: (current: PortalState) => PortalState) => void; onClose: () => void; announce: (message: string) => void }) { const [drafts, setDrafts] = useState<Partial<Record<keyof MasterData, string>>>({}); const add = (key: keyof MasterData) => { const value = (drafts[key] ?? "").trim(); if (!value || value.length > 100) return announce("Enter a name up to 100 characters."); if (portal.masters[key].some((item) => item.toLowerCase() === value.toLowerCase())) return announce("That option already exists."); update((current) => ({ ...current, masters: { ...current.masters, [key]: [...current.masters[key], value] } })); setDrafts({ ...drafts, [key]: "" }); announce(`${value} added.`); }; return <Modal title="Administration settings" onClose={onClose} wide><p className="mb-4 text-sm leading-6 text-muted-foreground">Add, manage, and deactivate controlled master-data options. Existing records retain their saved values.</p><div className="grid gap-4 md:grid-cols-2">{(Object.keys(portal.masters) as (keyof MasterData)[]).map((key) => <section key={key} className="border border-border p-4"><p className="font-semibold capitalize">{key.replace(/([A-Z])/g, " $1")}</p><div className="mt-3 flex gap-2"><input aria-label={`New ${key}`} value={drafts[key] ?? ""} onChange={(event) => setDrafts({ ...drafts, [key]: event.target.value.slice(0, 100) })} placeholder={`Add ${key.replace(/([A-Z])/g, " $1").toLowerCase()}`} className="h-10 min-w-0 flex-1 rounded-md border border-input bg-background px-3 text-sm"/><button type="button" onClick={() => add(key)} className="h-10 rounded-md bg-primary px-3 text-sm font-semibold text-primary-foreground">Add</button></div>{portal.masters[key].length ? <div className="mt-3 flex flex-wrap gap-2">{portal.masters[key].map((item) => <span key={item} className="inline-flex items-center gap-2 rounded-full border border-border bg-panel px-2 py-1 text-xs">{item}<button type="button" onClick={() => { update((current) => ({ ...current, masters: { ...current.masters, [key]: current.masters[key].filter((value) => value !== item) } })); announce(`${item} deactivated.`); }} aria-label={`Deactivate ${item}`} className="text-danger">×</button></span>)}</div> : <p className="mt-3 text-sm text-muted-foreground">No managed options yet.</p>}</section>)}</div></Modal>; }
function Modal({ title, onClose, children, wide }: { title: string; onClose: () => void; children: React.ReactNode; wide?: boolean }) { return <div className="fixed inset-0 z-50 grid place-items-end bg-ink/35 p-0 md:place-items-center md:p-6"><section role="dialog" aria-modal="true" aria-label={title} className={`max-h-[92vh] w-full overflow-auto bg-popover shadow-2xl ${wide ? "max-w-3xl" : "max-w-xl"}`}><header className="sticky top-0 flex items-center justify-between border-b border-border bg-popover px-5 py-4"><h2 className="text-lg font-semibold">{title}</h2><button onClick={onClose} className="grid size-9 place-items-center rounded-md bg-secondary" aria-label="Close"><X className="size-4"/></button></header><div className="p-5">{children}</div></section></div>; }
function TextField({ label, value, onChange, required, name, type = "text" }: { label: string; value: string; onChange: (value: string) => void; required?: boolean; name?: string; type?: string }) { const inputId = name ?? label.toLowerCase().replace(/[^a-z0-9]+/g, "-"); return <label htmlFor={inputId} className="block text-sm font-medium">{label}{required && <span className="ml-1 text-danger">Required</span>}<input id={inputId} name={name} type={type} required={required} value={value} onChange={(event) => onChange(event.target.value)} className="mt-1.5 h-11 w-full rounded-md border border-input bg-background px-3 text-sm outline-none focus:ring-2 focus:ring-ring"/></label>; }
function FormField({ item, value, onChange, portal }: { item: { key: string; label: string; required?: boolean; kind?: "text" | "date" | "select"; options?: string[]; master?: keyof MasterData }; value: string; onChange: (value: string) => void; portal: PortalState }) { const options = item.master ? portal.masters[item.master] : item.options ?? []; if (item.kind === "select" || item.master) return <label className="block text-sm font-medium">{item.label}{item.required && <span className="ml-1 text-danger">Required</span>}<select value={value} onChange={(event) => onChange(event.target.value)} className="mt-1.5 h-11 w-full rounded-md border border-input bg-background px-3 text-sm"><option value="">Select an option</option>{options.map((option) => <option key={option}>{option}</option>)}</select>{!options.length && <span className="mt-1 block text-xs text-muted-foreground">Manage options in Administration settings.</span>}</label>; return <TextField label={item.label} required={item.required} value={value} onChange={(next) => onChange(next.slice(0, 120))} type={item.kind === "date" ? "date" : "text"}/>; }
function LinkedSelector({ label, records, links, onChange, onCreate }: { label: string; records: RecordItem[]; links: string[]; onChange: (ids: string[]) => void; onCreate: () => void }) { const [query, setQuery] = useState(""); const visible = records.filter((record) => `${record.reference} ${record.title}`.toLowerCase().includes(query.toLowerCase())); return <div className="border border-border p-3"><div className="flex items-center justify-between gap-2"><label className="text-sm font-medium">{label}</label><button type="button" onClick={onCreate} className="text-xs font-semibold text-steel">Create new</button></div><input aria-label={`Search ${label}`} value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search existing records" className="mt-2 h-9 w-full rounded-md border border-input bg-background px-2 text-sm"/><select aria-label={`Select ${label}`} value="" onChange={(event) => { const value = event.target.value; if (value && !links.includes(value)) onChange([...links, value]); }} className="mt-2 h-9 w-full rounded-md border border-input bg-background px-2 text-sm"><option value="">Select a record</option>{visible.map((record) => <option key={record.id} value={record.id}>{record.reference} · {record.title}</option>)}</select>{links.length ? <p className="mt-2 text-xs text-muted-foreground">{links.length} linked record{links.length === 1 ? "" : "s"} selected.</p> : null}</div>; }
function Selector({ label, options, emptyLabel }: { label: string; options: string[]; emptyLabel: string }) { return <label className="block text-sm font-medium">{label}<select disabled={!options.length} className="mt-1.5 h-11 w-full rounded-md border border-input bg-background px-3 text-sm disabled:opacity-60">{options.length ? options.map((option) => <option key={option}>{option}</option>) : <option>{emptyLabel}</option>}</select></label>; }
function HeaderAction({ label, icon: Icon, onClick }: { label: string; icon: typeof Bell; onClick: () => void }) { return <button onClick={onClick} className="grid size-10 shrink-0 place-items-center rounded-lg border border-border bg-panel" aria-label={label}><Icon className="size-4"/></button>; }
function Brand() { return <div className="flex min-w-0 items-center gap-3"><div className="grid size-9 shrink-0 place-items-center rounded-lg bg-sidebar-primary font-mono text-[11px] font-semibold tracking-[0.15em] text-sidebar-primary-foreground">SS</div><div className="min-w-0"><p className="truncate text-sm font-semibold">Six Sense Mobility</p><p className="font-mono text-[10px] uppercase tracking-[0.14em] text-muted-foreground">Operations portal</p></div></div>; }
function AreaNav({ area, active, onClick }: { area: typeof areas[number]; active: boolean; onClick: () => void }) { const Icon = area.icon; return <button onClick={onClick} className={`grid w-full grid-cols-[1.2rem_minmax(0,1fr)] items-center gap-3 rounded-lg px-3 py-2.5 text-left text-sm ${active ? "bg-sidebar-primary text-sidebar-primary-foreground" : "text-sidebar-foreground hover:bg-secondary"}`}><Icon className="size-4 shrink-0"/><span className="truncate">{area.name}</span></button>; }
function Empty({ onCreate, label = "Create record" }: { onCreate: () => void; label?: string }) { return <div className="grid place-items-center px-5 py-12 text-center"><div className="grid size-11 place-items-center rounded-full bg-secondary text-secondary-foreground"><ClipboardCheck className="size-5"/></div><h3 className="mt-4 font-semibold">No records yet</h3><p className="mt-2 max-w-sm text-sm leading-6 text-muted-foreground">Create the first confirmed record to begin this workflow.</p><button onClick={onCreate} className="mt-4 inline-flex h-10 items-center gap-2 rounded-md bg-primary px-4 text-sm font-semibold text-primary-foreground"><Plus className="size-4"/>{label}</button></div>; }
function Metric({ label, value, detail, tone }: { label: string; value: string; detail: string; tone: "danger" | "steel" | "moss" | "warning" }) { return <div className="border border-border bg-card p-4"><div className="flex justify-between"><p className="font-mono text-[10px] uppercase tracking-[0.14em] text-muted-foreground">{label}</p><span className={`size-2 rounded-full ${tone === "danger" ? "bg-danger" : tone === "steel" ? "bg-steel" : tone === "moss" ? "bg-moss" : "bg-warning"}`}/></div><p className="mt-3 text-3xl font-semibold">{value}</p><p className="mt-1 text-xs text-muted-foreground">{detail}</p></div>; }
function Status({ status }: { status: RecordStatus }) { const tone = status === "Released" || status === "Approved" ? "bg-accent text-accent-foreground" : status === "Archived" ? "bg-secondary text-secondary-foreground" : "bg-panel-strong text-foreground"; return <span className={`inline-flex rounded-full px-2.5 py-1 font-mono text-[10px] uppercase tracking-[0.08em] ${tone}`}>{status}</span>; }
